    /// <summary>
    /// AdamW over many tensors in a few passes: the global gradient norm clipped to <paramref name="maxNorm"/> (0: no
    /// clipping), p ← p · <paramref name="decay"/>, then Adam with the bias-corrected <paramref name="lr"/>, as
    /// <see cref="AdamStep"/> computes it; with <paramref name="zeroGradients"/> the gradients are zeroed for the next step.
    /// <paramref name="cache"/> keeps the device tables between calls (dispose it when done). False when the device has no
    /// such pass.
    /// </summary>
    /// <remarks>Runs <see cref="Ops.FusedAdamW"/>: <c>FusedAdamWKernel</c>.</remarks>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public bool FusedAdamW(ReadOnlySpan<(Storage P, Storage G, Storage M, Storage V, int N)> tensors, ref IDisposable? cache, float maxNorm, float lr, float decay, float beta1, float beta2, float eps, bool zeroGradients)
    {
        return _kernels is null && _moves is null ? FusedAdamWKernel(tensors, ref cache, maxNorm, lr, decay, beta1, beta2, eps, zeroGradients) : ReferenceEquals(_kernels, s_guardedKernels) ? FusedAdamWGuarded(tensors, ref cache, maxNorm, lr, decay, beta1, beta2, eps, zeroGradients) : FusedAdamWScoped(tensors, ref cache, maxNorm, lr, decay, beta1, beta2, eps, zeroGradients);
    }

    [MethodImpl(MethodImplOptions.NoInlining)]
    private bool FusedAdamWScoped(ReadOnlySpan<(Storage P, Storage G, Storage M, Storage V, int N)> tensors, ref IDisposable? cache, float maxNorm, float lr, float decay, float beta1, float beta2, float eps, bool zeroGradients)
    {
        using var operation = EnterOperation();
        Traced(OperationIndex.FusedAdamW);
        return RefusedKernelsFallBack ? FusedAdamWGuarded(tensors, ref cache, maxNorm, lr, decay, beta1, beta2, eps, zeroGradients) : FusedAdamWKernel(tensors, ref cache, maxNorm, lr, decay, beta1, beta2, eps, zeroGradients);
    }

    // FusedAdamW on a device whose refused kernels fall back (BuildsKernelsWhenUsed): the caller's path when its kernel is refused.
    [MethodImpl(MethodImplOptions.NoInlining)]
    private bool FusedAdamWGuarded(ReadOnlySpan<(Storage P, Storage G, Storage M, Storage V, int N)> tensors, ref IDisposable? cache, float maxNorm, float lr, float decay, float beta1, float beta2, float eps, bool zeroGradients)
    {
        try
        {
            return FusedAdamWKernel(tensors, ref cache, maxNorm, lr, decay, beta1, beta2, eps, zeroGradients);
        }
        catch (KernelUnavailableException refused) when (OwnsKernel(OperationIndex.FusedAdamW))
        {
            FellBack(Ops.FusedAdamW.Name, refused, "the caller's path");
            return default;
        }
    }

